		hc.start(HashingContext.HASH_SHA256)
		hc.update(data)
		var h := hc.finish()
		var t1 := Time.get_ticks_usec()
		print("sha256 ", sz, " bytes: ", (t1 - t0) / 1000.0, " ms; digest size=", h.size())
	# var_to_bytes timing on an snapshot-like dictionary
	var snap := {}
	for k in range(32):
		var arr := PackedInt32Array(); arr.resize(2500) # ~10KB per block
