		var rows := []
		for i in 300: rows.append([i, i*2, i*3, i*4, i*5, i*6])
		snap["block_%d" % k] = {"v": 1, "a": arr, "rows": rows, "n": 300}
	var t0 := Time.get_ticks_usec()
	var total := 0
	var parts := []
	for k in snap:
		var bb := var_to_bytes(snap[k])
		total += bb.size()
		parts.append(bb)
	var t1 := Time.get_ticks_usec()
	print("var_to_bytes 32 blocks total=", total, " bytes in ", (t1 - t0)/1000.0, " ms")
	var t2 := Time.get_ticks_usec()
	var dd2 = snap.duplicate(true)
	print("deep duplicate 32 blocks ", (Time.get_ticks_usec() - t2)/1000.0, " ms")
	var t3 := Time.get_ticks_usec()
	for p in parts: bytes_to_var(p)
	print("bytes_to_var 32 blocks ", (Time.get_ticks_usec() - t3)/1000.0, " ms")
	quit()

func _enc32(v: int) -> PackedByteArray:
	var p := PackedByteArray(); p.resize(4); p.encode_u32(0, v); return p
