var th: Thread
var mu := Mutex.new()
var status := {"state": 0}

func _worker(payload: PackedByteArray, path: String) -> int:
	mu.lock(); status["state"] = 1; mu.unlock()
	var f := FileAccess.open(path, FileAccess.WRITE)
	var ok := f.store_buffer(payload)
	f.flush(); f.close()
	OS.delay_msec(20)
	mu.lock(); status["state"] = 2; mu.unlock()
	return 7

func _init() -> void:
	var path := OS.get_user_data_dir().path_join("adr0006probe/w.bin")
	var data := PackedByteArray(); data.resize(300000)
	th = Thread.new()
	var t0 := Time.get_ticks_usec()
	var err := th.start(_worker.bind(data, path))
	print("start err=", err, " in ", (Time.get_ticks_usec() - t0)/1000.0, " ms; data size after bind=", data.size())
	var polls := 0
	while th.is_alive():
		polls += 1
		OS.delay_msec(2)
	mu.lock(); var st = status["state"]; mu.unlock()
	print("alive polls=", polls, " status=", st, " wait_to_finish ret=", th.wait_to_finish(), " is_started=", th.is_started())
	# start a thread that blocks 8 seconds then quit the tree with it alive
	var slow := Thread.new()
	slow.start(func(): OS.delay_msec(8000))
	print("slow alive=", slow.is_alive(), " now quitting at ", Time.get_ticks_msec())
	var t = Time.get_ticks_msec()
	quit()
